import org.jsoup.nodes.Document;
import org.jsoup.nodes.LeafNode;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void createTextNode_fromString() {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void createTextNode_fromNull_throwsNullPointerException() {
        assertThrows(NullPointerException.class, () -> new TextNode(null));
    }

    @Test
    public void nodeName_isText() {
        String text = "Hello";
        TextNode node = new TextNode(text);
        assertEquals("text", node.nodeName());
    }

    @Test
    public void text_getsTextFromNode() {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
    }

    @Test
    public void text_setsTextOnNode() {
        String originalText = "Hello";
        TextNode node = new TextNode(originalText);
        String newText = "New Hello";
        node.text(newText);
        assertEquals(newText, node.text());
    }

    @Test
    public void getWholeText_returnsAllText() {
        String text = "Hello\nWorld!";
        TextNode node = new TextNode(text);
        assertEquals(text, node.getWholeText());
    }

    @Test
    public void isBlank_returnsTrueForEmptyString() {
        assertTrue(TextNode.isBlank(""));
    }

    @Test
    public void isBlank_returnsFalseForNonEmptyString() {
        assertFalse(TextNode.isBlank("Hello"));
    }

    @Test
    public void splitText_splitsAtOffset() throws IOException {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        int offset = 7;
        TextNode firstPart = node.splitText(offset);
        assertEquals(6, firstPart.text().length());
        assertEquals("World!", firstPart.text());
    }

    @Test
    public void splitText_splitsAtOffset_atEnd_ofString() throws IOException {
        String text = "Hello";
        TextNode node = new TextNode(text);
        int offset = text.length();
        TextNode secondPart = node.splitText(offset);
        assertTrue(secondPart.isBlank());
    }

    @Test
    public void outerHtmlHead_appendsToAppendable() throws IOException, InterruptedException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        Document.OutputSettings settings = Document.OutputSettings.empty();
        TextNode node = new TextNode("Hello");
        node.outerHtmlHead(accum, 0, settings);
        String html = out.toString();
        assertEquals("<p>Hello</p>", html);
    }

    @Test
    public void outerHtmlTail_appendsToAppendable() throws IOException, InterruptedException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        Document.OutputSettings settings = Document.OutputSettings.empty();
        TextNode node = new TextNode("Hello");
        node.outerHtmlTail(accum, 0, settings);
        String html = out.toString();
        assertEquals("<p></p>", html);
    }

    @Test
    public void toString_returnsEncodedText() throws IOException {
        String text = "Hello, World!";
        TextNode node = new TextNode(text);
        assertEquals("Hello,World!", node.toString());
    }

    @Test
    public void clone_returnsSameTextNode() {
        String text = "Hello";
        TextNode node = new TextNode(text);
        TextNode cloned = node.clone();
        assertEquals(node.text(), cloned.text());
    }

    @Test
    public void createFromEncoded_decodesCorrectly() throws IOException {
        String encodedText = "Hello%2C+World%21";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertEquals("Hello, World!", node.text());
    }

    @Test
    public void normaliseWhitespace_replacesWithSpaces() {
        assertTrue(TextNode.normaliseWhitespace("Hello\r\nWorld!"));
        assertTrue(TextNode.normaliseWhitespace("\n  Hello\nWorld!\r"));
    }

    @Test
    public void stripLeadingWhitespace_removesTrailingSpaces() {
        String text = "   Hello World!";
        assertEquals("Hello World!", TextNode.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespace_returnsTrueForEndOfLine() {
        assertTrue(TextNode.lastCharIsWhitespace(new StringBuilder("\n")));
    }
}
